(()=> {
  for (const reading of TABI_EXTENDED_READINGS) {
    const original=TABI_STUDIO_DATA.stories.find(story=>story.id===reading.id);
    const lines=[], sections=[];
    for (const row of reading.text.split('\n')) {
      if (row.startsWith('# ')) {
        sections.push({title:row.slice(2),start:lines.length});
      } else if (row.includes('|')) {
        const [jp,en]=row.split('|');
        lines.push([jp,en]);
      }
    }
    Object.assign(original,{lines,sections,questions:reading.questions});
    if(reading.id==='delay')original.kind='Story';
  }
})();
